          />
        </section>

        <section className="pj-card">
          <div className="pj-card-h"><h3>Instructions</h3></div>
          <EmptyState
            icon={I.penLine}
            title="No custom instructions yet"
            hint="Authoring instructions saved on this project's intelligence profile will appear here."
          />
        </section>

      </aside>
    </div>
  );
