       linked_submission_outcome_id, linked_precedent_id, metadata
     ) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9,COALESCE($10,'unverified'),$11,$12,COALESCE($13::jsonb,'{}'::jsonb))
