      p.outcomeType, p.outcomeDate ?? null, p.approvalDate ?? null, p.timeToResolutionDays ?? null,
      p.evidenceNote ?? null, p.verificationStatus ?? null, p.linkedSubmissionOutcomeId ?? null,
